'use client'

import {
  closestCenter,
  DndContext,
  type DragEndEvent,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from '@dnd-kit/core'
import { arrayMove, sortableKeyboardCoordinates } from '@dnd-kit/sortable'
import type { RankingInfo } from '@tanstack/match-sorter-utils'
import {
  type ColumnDef,
  type ColumnFiltersState,
  flexRender,
  getCoreRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type OnChangeFn,
  type PaginationState,
  type Row,
  type RowSelectionState,
  type SortingState,
  type Table,
  type TableOptions,
  useReactTable,
  type VisibilityState,
} from '@tanstack/react-table'
import { ArrowDown, ArrowUp, ArrowUpDown } from 'lucide-react'
import {
  type CSSProperties,
  type Dispatch,
  type ReactNode,
  type SetStateAction,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from 'react'
import { cn } from '@/lib/utils'
import type { ProButtonSize } from '../base/button'
import { ProPagination } from '../pagination'
import { getPinnedColumnClassName, getPinnedColumnStyle, ProTableBody } from './body'
import { ProTableBulkActions } from './bulk-actions'
import { ProTableSearchBar } from './search-bar'
import {
  type ColumnFilterMeta,
  type ProTableTableOptions,
  sortRowsByRank,
  useProTableColumnState,
  useProTablePinnedColumnOffsets,
  withProTableColumnDefaults,
} from './table-state'
import { ProTableToolbarActions, type TableSize } from './toolbar-actions'
import {
  type ProTableStateValue,
  type UrlColumnFilterConfig,
  useProTableUrlStateValue,
} from './url-state'

/** Pagination, sorting, and filter state managed by ProTable. */
export interface ProTableState extends ProTableStateValue {}

/** Maps a table column filter to a URL search parameter. */
export type ColumnFilterConfig = UrlColumnFilterConfig

/** Synchronizes ProTable state with a router's search parameters. */
export const useProTableUrlState = useProTableUrlStateValue

interface ProTableDragSortOptions<TData> {
  rowKey: Extract<keyof TData, string | number>
  onDragSortEnd?: (newData: TData[]) => void
}

export type ProTableRowKey<TData> =
  | Extract<keyof TData, string | number>
  | ((record: TData) => string | number)

interface ProTableRenderContext<TData> {
  table: Table<TData>
  rows: Row<TData>[]
  selectedRows: Row<TData>[]
  tableSize: TableSize
  size?: ProButtonSize
}

type ProTableToolbarSlot<TData> = ReactNode | ((context: ProTableRenderContext<TData>) => ReactNode)

/** Search, actions, and table controls rendered around the table header. */
export interface ProTableToolbarOptions<TData> {
  actions?: ProTableToolbarSlot<TData>
  searchPlacement?: 'header' | 'below'
  density?: boolean
  columns?: boolean
  onRefresh?: () => void
}

declare module '@tanstack/react-table' {
  interface ColumnMeta<TData, TValue> {
    pinned?: 'left' | 'right'
    align?: 'left' | 'center' | 'right'
    className?: string
    search?:
      | boolean
      | {
          placeholder?: string
        }
    filter?: ColumnFilterMeta<TData>
    __proTableFixedSize?: number
  }
  interface FilterMeta {
    itemRank?: RankingInfo
  }
}

function useProTable<TData, TValue>({
  columns,
  data,
  setData,
  rowKey,
  size,
  paginationOptions,
  dragSort,
  tableOptions,
  manual = false,
  requestTotal,
  pagination,
  setPagination,
  sorting,
  setSorting,
  columnFilters,
  setColumnFilters,
}: {
  columns: ColumnDef<TData, TValue>[]
  data: TData[]
  setData: Dispatch<SetStateAction<TData[]>>
  rowKey?: ProTableRowKey<TData>
  pagination: PaginationState
  setPagination: Dispatch<SetStateAction<PaginationState>>
  sorting: SortingState
  setSorting: Dispatch<SetStateAction<SortingState>>
  columnFilters: ColumnFiltersState
  setColumnFilters: Dispatch<SetStateAction<ColumnFiltersState>>
  size?: ProButtonSize
  paginationOptions?: false
  dragSort?: false | ProTableDragSortOptions<TData>
  tableOptions?: ProTableTableOptions
  manual?: boolean
  requestTotal?: number
}) {
  const [rowSelection, setRowSelection] = useState<RowSelectionState>({})
  const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({})
  const [tableSize, setTableSize] = useState<TableSize>('default')
  const tableRef = useRef<HTMLTableElement>(null)
  const tableColumns = useMemo(() => withProTableColumnDefaults(columns), [columns])
  const rankedSortedRowModel = useMemo(() => {
    const sortedRowModel = getSortedRowModel<TData>()

    return (table: Table<TData>) => {
      const getSorted = sortedRowModel(table)

      return () => {
        const rowModel = getSorted()
        if (table.options.manualSorting || table.getState().sorting.length > 0) return rowModel

        const rankedColumnId = rowModel.rows
          .flatMap((row) =>
            Object.keys(row.columnFiltersMeta).filter(
              (columnId) => !!row.columnFiltersMeta[columnId]?.itemRank,
            ),
          )
          .at(0)
        if (!rankedColumnId) return rowModel

        return {
          ...rowModel,
          rows: sortRowsByRank(rowModel.rows, rankedColumnId),
          flatRows: sortRowsByRank(rowModel.flatRows, rankedColumnId),
        }
      }
    }
  }, [])
  const columnState = useProTableColumnState(tableColumns, tableOptions)
  const resetToFirstPage = useCallback(() => {
    setPagination((current) => ({ ...current, pageIndex: 0 }))
  }, [setPagination])
  const handleSortingChange = useCallback<OnChangeFn<SortingState>>(
    (updater) => {
      setSorting(updater)
      resetToFirstPage()
    },
    [resetToFirstPage, setSorting],
  )
  const handleColumnFiltersChange = useCallback<OnChangeFn<ColumnFiltersState>>(
    (updater) => {
      setColumnFilters(updater)
      resetToFirstPage()
    },
    [resetToFirstPage, setColumnFilters],
  )
  const reactTableOptions: TableOptions<TData> = {
    data,
    columns: tableColumns,
    state: {
      sorting,
      columnVisibility,
      rowSelection,
      columnFilters,
      columnOrder: columnState.columnOrder,
      columnPinning: columnState.columnPinning,
      pagination,
    },
    enableRowSelection: true,
    enableColumnPinning: columnState.pinningEnabled,
    onRowSelectionChange: setRowSelection,
    onSortingChange: handleSortingChange,
    onColumnFiltersChange: handleColumnFiltersChange,
    onColumnVisibilityChange: setColumnVisibility,
    onColumnOrderChange: columnState.setColumnOrder,
    onColumnPinningChange: columnState.handleColumnPinningChange,
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: rankedSortedRowModel,
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
  }
  if (manual) {
    reactTableOptions.manualPagination = true
    reactTableOptions.manualSorting = true
    reactTableOptions.manualFiltering = true
    reactTableOptions.rowCount = requestTotal
  }
  const resolvedRowKey = rowKey ?? dragSort?.rowKey
  if (resolvedRowKey !== undefined) {
    reactTableOptions.getRowId = (row) =>
      String(typeof resolvedRowKey === 'function' ? resolvedRowKey(row) : row[resolvedRowKey])
  }
  const table = useReactTable(reactTableOptions)
  const pageCount = table.getPageCount()

  useEffect(() => {
    if (paginationOptions === false || pageCount <= 0 || pagination.pageIndex < pageCount) return
    setPagination((current) => ({ ...current, pageIndex: pageCount - 1 }))
  }, [pageCount, pagination.pageIndex, paginationOptions, setPagination])

  const dragSortEnabled = !!dragSort
  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    }),
  )
  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const { active, over } = event
      if (!over || active.id === over.id) return

      const rows = table.getRowModel().rows
      const oldIndex = rows.findIndex((row) => row.id === String(active.id))
      const newIndex = rows.findIndex((row) => row.id === String(over.id))
      if (oldIndex === -1 || newIndex === -1) return

      const oldDataIndex = data.indexOf(rows[oldIndex].original)
      const newDataIndex = data.indexOf(rows[newIndex].original)
      if (oldDataIndex === -1 || newDataIndex === -1) return

      const nextData = arrayMove(data, oldDataIndex, newDataIndex)
      if (nextData === data) return

      setData(nextData)
      if (dragSort) dragSort.onDragSortEnd?.(nextData)
    },
    [data, dragSort, setData, table],
  )
  const pinnedOffsets = useProTablePinnedColumnOffsets(table, tableRef, dragSortEnabled)
  const rows = table.getRowModel().rows
  const selectedRows = table.getFilteredSelectedRowModel().rows
  const visibleColumns = table.getVisibleLeafColumns()
  const visibleColumnCount = visibleColumns.length + (dragSortEnabled ? 1 : 0)
  const renderContext: ProTableRenderContext<TData> = {
    table,
    rows,
    selectedRows,
    tableSize,
    size,
  }

  return {
    table,
    tableRef,
    tableSize,
    setTableSize,
    rows,
    selectedRows,
    visibleColumns,
    visibleColumnCount,
    renderContext,
    pinnedOffsets,
    sensors,
    handleDragEnd,
    dragSortEnabled,
    defaultColumnOrder: columnState.defaultColumnOrder,
    defaultColumnPinning: columnState.defaultColumnPinning,
  }
}

function renderToolbarSlot<TData>(
  toolbar: ProTableToolbarSlot<TData> | undefined,
  context: ProTableRenderContext<TData>,
) {
  if (toolbar === false) return undefined
  if (typeof toolbar === 'function') return toolbar(context)
  return toolbar
}

function getTablePaddingClass(size: TableSize) {
  if (size === 'compact') return 'py-1'
  if (size === 'middle') return 'py-2'
  return 'py-3'
}

function getAriaSort(canSort: boolean, sorted: false | 'asc' | 'desc') {
  if (!canSort) return undefined
  if (sorted === 'asc') return 'ascending'
  if (sorted === 'desc') return 'descending'
  return 'none'
}

function renderSortIcon(sorted: false | 'asc' | 'desc') {
  if (sorted === 'asc') return <ArrowUp size={14} />
  if (sorted === 'desc') return <ArrowDown size={14} />
  return <ArrowUpDown size={14} className="opacity-40" />
}

export interface ProTableProps<TData, TValue = unknown> {
  columns: ColumnDef<TData, TValue>[]
  data?: TData[]
  rowKey?: ProTableRowKey<TData>
  request?: (
    params: ProTableState,
  ) => Promise<{ data: TData[]; total?: number }> | { data: TData[]; total?: number }
  initialState?: Partial<ProTableState>
  onChange?: (state: ProTableState) => void
  header?: ReactNode | ((context: ProTableRenderContext<TData>) => ReactNode)
  toolbar?: false | ProTableToolbarOptions<TData>
  size?: ProButtonSize
  bulkToolbar?: false | ProTableToolbarSlot<TData>
  pagination?: false
  dragSort?: false | ProTableDragSortOptions<TData>
  loading?: boolean | { rows?: number }
  layout?: 'full' | 'auto'
  table?: ProTableTableOptions
  className?: string
}

/** Feature-rich local or remote TanStack data table. */
export function ProTable<TData, TValue>({
  columns,
  data,
  rowKey,
  request,
  initialState,
  onChange,
  header,
  toolbar,
  size,
  bulkToolbar,
  pagination,
  dragSort,
  loading,
  layout,
  table,
  className,
}: ProTableProps<TData, TValue>) {
  const dragContextId = useId()
  const toolbarButtonSize = size ?? 'icon'
  const [tableData, setTableData] = useState<TData[]>(data ?? [])
  const [requestLoading, setRequestLoading] = useState(false)
  const [requestError, setRequestError] = useState<unknown>()
  const [requestTotal, setRequestTotal] = useState<number>()
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>(
    initialState?.columnFilters ?? [],
  )
  const [sorting, setSorting] = useState<SortingState>(initialState?.sorting ?? [])
  const [paginationState, setPagination] = useState<PaginationState>(
    initialState?.pagination ?? {
      pageIndex: 0,
      pageSize: 10,
    },
  )

  useEffect(() => {
    const nextPagination = initialState?.pagination
    const nextSorting = initialState?.sorting
    const nextColumnFilters = initialState?.columnFilters

    if (nextPagination) {
      setPagination((current) =>
        current.pageIndex === nextPagination.pageIndex &&
        current.pageSize === nextPagination.pageSize
          ? current
          : nextPagination,
      )
    }
    if (nextSorting) {
      setSorting((current) =>
        JSON.stringify(current) === JSON.stringify(nextSorting) ? current : nextSorting,
      )
    }
    if (nextColumnFilters) {
      setColumnFilters((current) =>
        JSON.stringify(current) === JSON.stringify(nextColumnFilters) ? current : nextColumnFilters,
      )
    }
  }, [initialState?.columnFilters, initialState?.pagination, initialState?.sorting])
  const state = useMemo<ProTableState>(
    () => ({ pagination: paginationState, sorting, columnFilters }),
    [paginationState, sorting, columnFilters],
  )
  const mountedRef = useRef(false)

  useEffect(() => {
    if (request) return
    setTableData(data ?? [])
  }, [data, request])

  useEffect(() => {
    if (!mountedRef.current) {
      mountedRef.current = true
      return
    }
    onChange?.(state)
  }, [onChange, state])

  useEffect(() => {
    if (!request) return

    let canceled = false
    setRequestLoading(true)
    setRequestError(undefined)

    Promise.resolve(request(state))
      .then((result) => {
        if (canceled) return
        setTableData(result.data)
        setRequestTotal(result.total)
      })
      .catch((error) => {
        if (canceled) return
        setRequestError(error)
        setTableData([])
        setRequestTotal(undefined)
      })
      .finally(() => {
        if (!canceled) setRequestLoading(false)
      })

    return () => {
      canceled = true
    }
  }, [request, state])

  const toolbarOptions = toolbar === false ? undefined : toolbar
  const searchPlacement = toolbarOptions?.searchPlacement ?? 'below'
  const loadingRows = typeof loading === 'object' ? (loading.rows ?? 5) : 5
  const loadingEnabled = (loading !== undefined && loading !== false) || requestLoading
  const proTable = useProTable({
    columns,
    data: tableData,
    setData: setTableData,
    rowKey,
    size: toolbarButtonSize,
    paginationOptions: pagination,
    dragSort,
    tableOptions: table,
    manual: !!request,
    requestTotal,
    pagination: paginationState,
    setPagination,
    sorting,
    setSorting,
    columnFilters,
    setColumnFilters,
  })
  const isFullLayout = (layout ?? 'full') === 'full'
  const headerContent = typeof header === 'function' ? header(proTable.renderContext) : header
  const toolbarActions = renderToolbarSlot(toolbarOptions?.actions, proTable.renderContext)
  const bulkActions = renderToolbarSlot(bulkToolbar, proTable.renderContext)
  const tableState = proTable.table.getState()
  const stickyHeader = table?.stickyHeader ?? true
  const paddingClass = getTablePaddingClass(proTable.tableSize)
  const fixedColumnsWidth = proTable.visibleColumns.reduce(
    (total, column) => total + (column.columnDef.meta?.__proTableFixedSize ?? 0),
    proTable.dragSortEnabled ? proTable.pinnedOffsets.dragWidth : 0,
  )
  const minimumTableWidth = proTable.visibleColumns.reduce(
    (total, column) => total + (column.columnDef.meta?.__proTableFixedSize ?? column.getSize()),
    proTable.dragSortEnabled ? proTable.pinnedOffsets.dragWidth : 0,
  )
  const flexibleColumnCount = proTable.visibleColumns.filter(
    (column) => column.columnDef.meta?.__proTableFixedSize === undefined,
  ).length
  const flexibleColumnWidth =
    flexibleColumnCount > 0
      ? `calc((100% - ${fixedColumnsWidth}px) / ${flexibleColumnCount})`
      : undefined
  const tableStyle = {
    '--pro-table-flex-column-width': flexibleColumnWidth,
    width: flexibleColumnCount > 0 ? '100%' : fixedColumnsWidth,
    minWidth: minimumTableWidth,
  } as CSSProperties
  const content = (
    <>
      <div
        className={cn(
          'w-full max-w-full overflow-auto rounded-md border',
          '[scrollbar-gutter:auto] [scrollbar-width:thin] [scrollbar-color:transparent_transparent] hover:[scrollbar-color:var(--muted-foreground)_transparent] [&::-webkit-scrollbar]:size-2 [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar-track]:shadow-none [&::-webkit-scrollbar-corner]:bg-transparent [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:border-0 [&::-webkit-scrollbar-thumb]:bg-transparent hover:[&::-webkit-scrollbar-thumb]:bg-muted-foreground/35',
        )}
      >
        <table
          ref={proTable.tableRef}
          data-slot="pro-table"
          className="w-full table-fixed border-separate border-spacing-0 caption-bottom text-sm [&_td]:border-b [&_td]:border-border [&_td]:transition-[border-color] [&_td]:duration-150 [&_th]:border-b [&_th]:border-border [&_tbody_tr:hover>td]:border-transparent [&_tbody_tr[data-state=selected]>td]:border-transparent"
          style={tableStyle}
        >
          <colgroup>
            {proTable.dragSortEnabled && (
              <col style={{ width: proTable.pinnedOffsets.dragWidth }} />
            )}
            {proTable.visibleColumns.map((column) => (
              <col
                key={column.id}
                style={
                  column.columnDef.meta?.__proTableFixedSize === undefined
                    ? { width: flexibleColumnWidth }
                    : { width: column.columnDef.meta.__proTableFixedSize }
                }
              />
            ))}
          </colgroup>
          <thead data-slot="pro-table-header">
            {proTable.table.getHeaderGroups().map((headerGroup) => (
              <tr key={headerGroup.id} data-slot="pro-table-row" className="bg-background">
                {proTable.dragSortEnabled && (
                  <th
                    data-slot="pro-table-head-cell"
                    data-pro-table-drag-column=""
                    scope="col"
                    className={cn(
                      'h-10 px-2 text-left align-middle font-medium whitespace-nowrap text-foreground [&:has([role=checkbox])]:pr-0 [&>[role=checkbox]]:translate-y-[2px]',
                      'sticky left-0 z-20 w-8 bg-background pr-0',
                      stickyHeader && 'top-0 z-30',
                    )}
                  >
                    <span className="sr-only">Reorder rows</span>
                  </th>
                )}
                {headerGroup.headers.map((header) => {
                  const canSort = !proTable.dragSortEnabled && header.column.getCanSort()
                  const sorted = header.column.getIsSorted()
                  const sortHandler = canSort ? header.column.getToggleSortingHandler() : undefined
                  const pinned = header.column.getIsPinned()
                  const align =
                    header.column.columnDef.meta?.align ??
                    (pinned === 'right' ? 'right' : pinned || undefined)
                  const ariaSort = getAriaSort(canSort, sorted)
                  const headerContent = header.isPlaceholder ? null : (
                    <div className="flex items-center gap-1.5">
                      {flexRender(header.column.columnDef.header, header.getContext())}
                      {canSort && (
                        <span className="text-muted-foreground" aria-hidden="true">
                          {renderSortIcon(sorted)}
                        </span>
                      )}
                    </div>
                  )

                  return (
                    <th
                      key={header.id}
                      data-slot="pro-table-head-cell"
                      scope={header.subHeaders.length > 0 ? 'colgroup' : 'col'}
                      colSpan={header.colSpan}
                      className={cn(
                        'h-10 px-2 text-left align-middle font-medium whitespace-nowrap text-foreground [&:has([role=checkbox])]:pr-0 [&_[role=checkbox]]:border-border [&_[role=checkbox]]:shadow-none [&>[role=checkbox]]:translate-y-[2px] dark:[&_[role=checkbox][data-state=unchecked]]:bg-transparent',
                        stickyHeader && 'sticky top-0 z-10 bg-inherit',
                        pinned && 'bg-background',
                        getPinnedColumnClassName(
                          header.column,
                          header.column.getIsPinned() && stickyHeader ? 'z-30' : undefined,
                        ),
                        align === 'center' && 'text-center [&>div]:justify-center',
                        align === 'right' && 'text-right [&>div]:justify-end',
                        align === 'left' && 'text-left [&>div]:justify-start',
                        header.column.columnDef.meta?.className,
                        canSort && 'cursor-pointer select-none',
                      )}
                      style={getPinnedColumnStyle(header.column, proTable.pinnedOffsets)}
                      data-pro-table-column-id={header.column.id}
                      aria-sort={ariaSort}
                      tabIndex={canSort ? 0 : undefined}
                      onClick={sortHandler}
                      onKeyDown={
                        canSort
                          ? (event) => {
                              if (event.key !== 'Enter' && event.key !== ' ') return
                              event.preventDefault()
                              sortHandler?.(event)
                            }
                          : undefined
                      }
                    >
                      {headerContent}
                    </th>
                  )
                })}
              </tr>
            ))}
          </thead>
          <tbody data-slot="pro-table-body" className="[&_tr:last-child>td]:border-b-0">
            <ProTableBody
              rows={proTable.rows}
              visibleColumns={proTable.visibleColumns}
              visibleColumnCount={proTable.visibleColumnCount}
              dragSort={proTable.dragSortEnabled}
              loading={loadingEnabled}
              loadingRows={loadingRows}
              paddingClass={paddingClass}
              emptyFallbackText={requestError ? 'Failed to load data' : undefined}
              pinnedOffsets={proTable.pinnedOffsets}
            />
          </tbody>
        </table>
      </div>
      {isFullLayout && <div className="min-h-0 flex-1" aria-hidden="true" />}
      {pagination !== false && (
        <div className={isFullLayout ? 'shrink-0' : undefined}>
          <ProPagination
            current={tableState.pagination.pageIndex + 1}
            pageCount={proTable.table.getPageCount()}
            pageSize={tableState.pagination.pageSize}
            total={proTable.table.getRowCount()}
            onPageChange={(page) => proTable.table.setPageIndex(page - 1)}
            onPageSizeChange={(pageSize) => {
              proTable.table.setPageSize(pageSize)
              proTable.table.setPageIndex(0)
            }}
          />
        </div>
      )}
    </>
  )
  return (
    <div
      className={cn(
        'max-w-full',
        isFullLayout ? 'flex h-full min-h-0 flex-col gap-3' : 'space-y-3',
        className,
      )}
    >
      {(headerContent != null || toolbar !== false) && (
        <div className="flex shrink-0 flex-col gap-2 md:flex-row md:items-start md:justify-between">
          {headerContent != null && <div className="min-w-0 shrink-0">{headerContent}</div>}
          {toolbar !== false && searchPlacement === 'header' && (
            <div className="min-w-0 flex-1">
              <ProTableSearchBar table={proTable.table} disabled={loadingEnabled} size={size} />
            </div>
          )}
          {toolbar !== false && (
            <ProTableToolbarActions
              table={proTable.table}
              disabled={loadingEnabled}
              actions={toolbarActions}
              size={size}
              columns={toolbarOptions?.columns ?? true}
              density={toolbarOptions?.density ?? true}
              refresh={toolbarOptions?.onRefresh}
              tableSize={proTable.tableSize}
              onTableSizeChange={proTable.setTableSize}
              defaultColumnOrder={proTable.defaultColumnOrder}
              defaultColumnPinning={proTable.defaultColumnPinning}
            />
          )}
        </div>
      )}
      {toolbar !== false && searchPlacement === 'below' && (
        <ProTableSearchBar table={proTable.table} disabled={loadingEnabled} size={size} />
      )}
      {proTable.dragSortEnabled && !loadingEnabled ? (
        <DndContext
          id={dragContextId}
          sensors={proTable.sensors}
          collisionDetection={closestCenter}
          onDragEnd={proTable.handleDragEnd}
        >
          {content}
        </DndContext>
      ) : (
        content
      )}
      {bulkActions != null && (
        <ProTableBulkActions table={proTable.table}>
          <div className="flex flex-wrap items-center justify-end gap-2">{bulkActions}</div>
        </ProTableBulkActions>
      )}
    </div>
  )
}

'use client'

import { SortableContext, useSortable, verticalListSortingStrategy } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { type Cell, type Column, flexRender, type Row } from '@tanstack/react-table'
import { GripVertical, Inbox } from 'lucide-react'
import type { CSSProperties, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { ProButton } from '../base/button'

const TABLE_ROW_CLASS_NAME =
  'group/row bg-background transition-colors duration-150 hover:bg-muted has-aria-expanded:bg-muted data-[state=selected]:bg-muted'
const TABLE_CELL_STATE_CLASS_NAME = 'bg-inherit bg-clip-padding'
const TABLE_ROW_COLOR_TRANSITION =
  'color 150ms cubic-bezier(0.4, 0, 0.2, 1), background-color 150ms cubic-bezier(0.4, 0, 0.2, 1), border-color 150ms cubic-bezier(0.4, 0, 0.2, 1)'

/** Measured left and right offsets for sticky table columns. */
export interface ProTablePinnedColumnOffsets {
  left: Record<string, number>
  right: Record<string, number>
  dragWidth: number
}

/** Renders loading, empty, static, and sortable ProTable rows. */
export function ProTableBody<TData>({
  rows,
  visibleColumns,
  visibleColumnCount,
  dragSort,
  loading,
  loadingRows,
  paddingClass,
  emptyFallbackText,
  pinnedOffsets,
}: {
  rows: Row<TData>[]
  visibleColumns: ReturnType<Row<TData>['getVisibleCells']>[number]['column'][]
  visibleColumnCount: number
  dragSort: boolean
  loading: boolean
  loadingRows: number
  paddingClass: string
  emptyFallbackText?: ReactNode
  pinnedOffsets: ProTablePinnedColumnOffsets
}) {
  const emptyRow = (
    <tr data-slot="pro-table-row" className={TABLE_ROW_CLASS_NAME}>
      <td
        data-slot="pro-table-cell"
        colSpan={visibleColumnCount}
        className={cn(
          'h-32 p-2 text-center align-middle whitespace-nowrap text-muted-foreground [&:has([role=checkbox])]:pr-0 [&_[role=checkbox]]:border-border [&_[role=checkbox]]:shadow-none [&>[role=checkbox]]:translate-y-[2px] dark:[&_[role=checkbox][data-state=unchecked]]:bg-transparent',
          TABLE_CELL_STATE_CLASS_NAME,
        )}
      >
        <div className="flex flex-col items-center gap-2">
          <Inbox className="size-8 opacity-40" />
          <span className="text-sm">{emptyFallbackText ?? 'No data'}</span>
        </div>
      </td>
    </tr>
  )

  if (loading) {
    return Array.from({ length: loadingRows }, (_, index) => (
      <tr
        // biome-ignore lint/suspicious/noArrayIndexKey: skeleton rows are fixed placeholders.
        key={`skeleton-row-${index}`}
        data-slot="pro-table-row"
        className={TABLE_ROW_CLASS_NAME}
      >
        {dragSort && (
          <td
            data-slot="pro-table-cell"
            data-pro-table-drag-column=""
            className={cn(
              'sticky left-0 z-20 w-8 p-2 pr-0 align-middle whitespace-nowrap [&:has([role=checkbox])]:pr-0 [&_[role=checkbox]]:border-border [&_[role=checkbox]]:shadow-none [&>[role=checkbox]]:translate-y-[2px] dark:[&_[role=checkbox][data-state=unchecked]]:bg-transparent',
              TABLE_CELL_STATE_CLASS_NAME,
            )}
          >
            <div
              data-slot="pro-table-skeleton"
              className="size-4 animate-pulse rounded-md bg-accent"
            />
          </td>
        )}
        {visibleColumns.map((column) => (
          <td
            key={column.id}
            data-slot="pro-table-cell"
            className={getPinnedColumnClassName(
              column,
              cn(
                'p-2 align-middle whitespace-nowrap transition-colors duration-150 [&:has([role=checkbox])]:pr-0 [&_[role=checkbox]]:border-border [&_[role=checkbox]]:shadow-none [&>[role=checkbox]]:translate-y-[2px] dark:[&_[role=checkbox][data-state=unchecked]]:bg-transparent',
                TABLE_CELL_STATE_CLASS_NAME,
                column.columnDef.meta?.className,
              ),
            )}
            style={getPinnedColumnStyle(column, pinnedOffsets)}
            data-pro-table-column-id={column.id}
          >
            <div
              data-slot="pro-table-skeleton"
              className="h-4 w-full animate-pulse rounded-md bg-accent"
            />
          </td>
        ))}
      </tr>
    ))
  }

  if (dragSort) {
    return (
      <SortableContext items={rows.map((row) => row.id)} strategy={verticalListSortingStrategy}>
        {rows.map((row) => (
          <SortableRow key={row.id} row={row} paddingClass={paddingClass}>
            {row.getVisibleCells().map((cell) => (
              <BodyCell
                key={cell.id}
                cell={cell}
                paddingClass={paddingClass}
                pinnedOffsets={pinnedOffsets}
              />
            ))}
          </SortableRow>
        ))}
        {rows.length === 0 && emptyRow}
      </SortableContext>
    )
  }

  if (rows.length === 0) return emptyRow
  return rows.map((row) => (
    <tr
      key={row.id}
      data-slot="pro-table-row"
      data-state={row.getIsSelected() && 'selected'}
      className={TABLE_ROW_CLASS_NAME}
    >
      {row.getVisibleCells().map((cell) => (
        <BodyCell
          key={cell.id}
          cell={cell}
          paddingClass={paddingClass}
          pinnedOffsets={pinnedOffsets}
        />
      ))}
    </tr>
  ))
}

function BodyCell<TData>({
  cell,
  paddingClass,
  pinnedOffsets,
}: {
  cell: Cell<TData, unknown>
  paddingClass: string
  pinnedOffsets: ProTablePinnedColumnOffsets
}) {
  const meta = cell.column.columnDef.meta
  const pinned = cell.column.getIsPinned()
  const align = meta?.align ?? (pinned === 'right' ? 'right' : pinned || undefined)
  const filter = meta?.filter
  const autoRender = !!filter && cell.column.columnDef.cell === undefined
  const values = getAutoFilterValues(autoRender, cell.getValue())
  const labels = new Map(
    autoRender ? filter.options.map((option) => [option.value, option.label] as const) : [],
  )

  return (
    <td
      data-slot="pro-table-cell"
      className={getPinnedColumnClassName(
        cell.column,
        cn(
          'p-2 align-middle whitespace-nowrap [&:has([role=checkbox])]:pr-0 [&_[role=checkbox]]:border-border [&_[role=checkbox]]:shadow-none [&>[role=checkbox]]:translate-y-[2px] dark:[&_[role=checkbox][data-state=unchecked]]:bg-transparent',
          TABLE_CELL_STATE_CLASS_NAME,
          paddingClass,
          align === 'center' && 'text-center',
          align === 'right' && 'text-right',
          align === 'left' && 'text-left',
          meta?.className,
        ),
      )}
      style={getPinnedColumnStyle(cell.column, pinnedOffsets)}
      data-pro-table-column-id={cell.column.id}
    >
      <TableCellContent autoRender={autoRender} values={values} labels={labels} cell={cell} />
    </td>
  )
}

function TableCellContent<TData>({
  autoRender,
  values,
  labels,
  cell,
}: {
  autoRender: boolean
  values: string[]
  labels: Map<string, string>
  cell: Cell<TData, unknown>
}) {
  if (!autoRender) return flexRender(cell.column.columnDef.cell, cell.getContext())
  if (values.length === 0) return <span className="text-muted-foreground">-</span>

  return (
    <div className="flex flex-wrap gap-1">
      {values.map((value) => (
        <span
          key={value}
          className="inline-flex shrink-0 items-center justify-center rounded-sm bg-secondary px-2 py-0.5 text-xs font-normal text-secondary-foreground"
        >
          {labels.get(value) ?? value}
        </span>
      ))}
    </div>
  )
}

function SortableRow<TData>({
  row,
  children,
  paddingClass,
}: {
  row: Row<TData>
  children: ReactNode
  paddingClass: string
}) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: row.id,
  })

  return (
    <tr
      ref={setNodeRef}
      data-slot="pro-table-row"
      data-state={row.getIsSelected() && 'selected'}
      className={TABLE_ROW_CLASS_NAME}
      style={{
        transform: CSS.Transform.toString(transform),
        transition: [transition, TABLE_ROW_COLOR_TRANSITION].filter(Boolean).join(', '),
        opacity: isDragging ? 0.5 : 1,
        position: isDragging ? 'relative' : undefined,
        zIndex: isDragging ? 10 : undefined,
      }}
    >
      <td
        data-slot="pro-table-cell"
        data-pro-table-drag-column=""
        className={cn(
          'p-2 align-middle whitespace-nowrap [&:has([role=checkbox])]:pr-0 [&_[role=checkbox]]:border-border [&_[role=checkbox]]:shadow-none [&>[role=checkbox]]:translate-y-[2px] dark:[&_[role=checkbox][data-state=unchecked]]:bg-transparent',
          paddingClass,
          TABLE_CELL_STATE_CLASS_NAME,
          'sticky left-0 z-20 w-8 pr-0',
        )}
      >
        <ProButton
          variant="link"
          size="icon-xs"
          {...attributes}
          {...listeners}
          className="cursor-grab text-muted-foreground no-underline hover:text-foreground hover:no-underline active:cursor-grabbing"
          aria-label="Drag to reorder"
        >
          <GripVertical />
        </ProButton>
      </td>
      {children}
    </tr>
  )
}

function getAutoFilterValues(autoRender: boolean, cellValue: unknown) {
  if (!autoRender) return []
  if (typeof cellValue === 'string') return [cellValue]
  if (Array.isArray(cellValue) && cellValue.every((item) => typeof item === 'string'))
    return cellValue
  return []
}

/** Returns sticky-column classes shared by table headers and body cells. */
export function getPinnedColumnClassName<TData>(
  column: Column<TData, unknown>,
  className?: string,
) {
  const pinned = column.getIsPinned()

  return cn(
    column.columnDef.meta?.__proTableFixedSize !== undefined && 'truncate',
    pinned && 'sticky z-10',
    className,
  )
}

/** Computes sticky-column inline offsets after measured widths are applied. */
export function getPinnedColumnStyle<TData>(
  column: Column<TData, unknown>,
  offsets: ProTablePinnedColumnOffsets,
): CSSProperties {
  const pinned = column.getIsPinned()
  const style: CSSProperties = {}
  const fixedSize = column.columnDef.meta?.__proTableFixedSize

  if (typeof fixedSize === 'number') {
    style.width = `${fixedSize}px`
    style.minWidth = `${fixedSize}px`
    style.maxWidth = `${fixedSize}px`
  } else {
    style.width = 'var(--pro-table-flex-column-width)'
  }

  if (pinned === 'left') {
    const left = offsets.left[column.id] ?? column.getStart('left') + offsets.dragWidth
    style.left = `${left}px`
  }
  if (pinned === 'right') {
    style.right = `${offsets.right[column.id] ?? column.getAfter('right')}px`
  }

  return style
}

'use client'

import type { Table } from '@tanstack/react-table'
import { X } from 'lucide-react'
import { type KeyboardEvent, type ReactNode, useEffect, useId, useRef, useState } from 'react'
import { ProButton } from '../base/button'

/** Floating keyboard-accessible actions for selected table rows. */
export function ProTableBulkActions<TData>({
  table,
  children,
}: {
  table: Table<TData>
  children?: ReactNode
}) {
  const selectedCount = table.getFilteredSelectedRowModel().rows.length
  const descriptionId = useId()
  const toolbarRef = useRef<HTMLDivElement>(null)
  const [announcement, setAnnouncement] = useState('')

  useEffect(() => {
    if (selectedCount === 0) return

    queueMicrotask(() =>
      setAnnouncement(
        `${selectedCount} ${selectedCount === 1 ? 'row' : 'rows'} selected. Bulk actions toolbar is available.`,
      ),
    )

    const timer = setTimeout(() => setAnnouncement(''), 3000)
    return () => clearTimeout(timer)
  }, [selectedCount])

  function handleKeyDown(event: KeyboardEvent) {
    const buttons = toolbarRef.current?.querySelectorAll('button')
    if (!buttons?.length) return

    const activeElement = document.activeElement
    const currentIndex =
      activeElement instanceof HTMLButtonElement ? Array.from(buttons).indexOf(activeElement) : -1

    switch (event.key) {
      case 'ArrowRight': {
        event.preventDefault()
        buttons[(currentIndex + 1) % buttons.length]?.focus()
        break
      }
      case 'ArrowLeft': {
        event.preventDefault()
        buttons[currentIndex <= 0 ? buttons.length - 1 : currentIndex - 1]?.focus()
        break
      }
      case 'Home': {
        event.preventDefault()
        buttons[0]?.focus()
        break
      }
      case 'End': {
        event.preventDefault()
        buttons[buttons.length - 1]?.focus()
        break
      }
      case 'Escape': {
        const target = event.target instanceof HTMLElement ? event.target : null
        const dropdownSelector =
          '[data-slot="dropdown-menu-trigger"], [data-slot="dropdown-menu-content"]'

        if (
          target?.closest(dropdownSelector) ||
          (activeElement instanceof HTMLElement && activeElement.closest(dropdownSelector))
        ) {
          return
        }

        event.preventDefault()
        table.resetRowSelection()
        break
      }
    }
  }

  if (selectedCount === 0) return null

  return (
    <>
      <div aria-live="polite" aria-atomic="true" className="sr-only" role="status">
        {announcement}
      </div>

      <div
        ref={toolbarRef}
        role="toolbar"
        aria-label={`Bulk actions for ${selectedCount} selected ${selectedCount === 1 ? 'row' : 'rows'}`}
        aria-describedby={descriptionId}
        tabIndex={-1}
        onKeyDown={handleKeyDown}
        className="fixed bottom-6 left-1/2 z-50 max-w-[calc(100vw-2rem)] -translate-x-1/2 rounded-xl transition-transform delay-100 duration-300 ease-out hover:scale-105 focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:outline-none"
      >
        <div className="flex items-center gap-x-2 overflow-x-auto rounded-xl border bg-background/95 p-2 shadow-xl backdrop-blur-lg supports-backdrop-filter:bg-background/60">
          <ProButton
            variant="outline"
            className="rounded-full"
            title="Clear selection (Escape)"
            tooltip="Clear selection (Escape)"
            onClick={() => table.resetRowSelection()}
          >
            <X />
          </ProButton>

          <div aria-hidden="true" className="h-5 w-px shrink-0 bg-border" />

          <div className="flex items-center gap-x-1 text-sm" id={descriptionId}>
            <span className="inline-flex min-w-8 items-center justify-center rounded-lg bg-primary px-2 py-0.5 text-xs font-medium text-primary-foreground">
              {selectedCount}
            </span>
            <span className="hidden sm:inline">{selectedCount === 1 ? 'row' : 'rows'}</span>
            selected
          </div>

          {children != null && (
            <>
              <div aria-hidden="true" className="h-5 w-px shrink-0 bg-border" />
              {children}
            </>
          )}
        </div>
      </div>
    </>
  )
}

import type { ColumnPinningState } from '@tanstack/react-table'

/** Default pinning for built-in utility columns. */
export function getSystemColumnPinning(id: string | undefined) {
  if (id === 'select' || id === 'drag') return 'left'
  if (id === 'actions' || id === 'operation') return 'right'
  return undefined
}

/** Calculates column order and pinning after a settings-panel drop. */
export function getColumnDropState({
  columnOrder,
  sortableOrder,
  columnPinning,
  activeId,
  overId,
  targetSide,
  pinningEnabled,
}: {
  columnOrder: string[]
  sortableOrder: string[]
  columnPinning: ColumnPinningState
  activeId: string
  overId: string
  targetSide: false | 'left' | 'right'
  pinningEnabled: boolean
}) {
  const oldIndex = sortableOrder.indexOf(activeId)
  const newIndex = sortableOrder.indexOf(overId)
  if (oldIndex === -1 || newIndex === -1 || oldIndex === newIndex) return undefined

  const nextSortableOrder = moveItem(sortableOrder, oldIndex, newIndex)
  const sortableIds = new Set(nextSortableOrder)
  const iterator = nextSortableOrder[Symbol.iterator]()
  const order = columnOrder.map((columnId) =>
    sortableIds.has(columnId) ? (iterator.next().value ?? columnId) : columnId,
  )

  if (!pinningEnabled) return { order, pinning: columnPinning }

  const leftIds = new Set(columnPinning.left ?? [])
  const rightIds = new Set(columnPinning.right ?? [])
  leftIds.delete(activeId)
  rightIds.delete(activeId)
  if (targetSide === 'left') leftIds.add(activeId)
  if (targetSide === 'right') rightIds.add(activeId)

  return {
    order,
    pinning: {
      left: [
        ...(columnPinning.left ?? []).filter((columnId) => !sortableIds.has(columnId)),
        ...nextSortableOrder.filter((columnId) => leftIds.has(columnId)),
      ],
      right: [
        ...nextSortableOrder.filter((columnId) => rightIds.has(columnId)),
        ...(columnPinning.right ?? []).filter((columnId) => !sortableIds.has(columnId)),
      ],
    },
  }
}

function moveItem<T>(items: T[], from: number, to: number) {
  const next = [...items]
  const [item] = next.splice(from, 1)
  if (item !== undefined) next.splice(to, 0, item)
  return next
}

'use client'

import type { Column, ColumnFiltersState, Table } from '@tanstack/react-table'
import { Search, X } from 'lucide-react'
import { useEffect, useState } from 'react'
import { ProButton, type ProButtonSize } from '../base/button'
import { Input } from '../base/fields/input'
import { Select } from '../base/fields/select'

/** Draft column search controls with explicit apply and reset actions. */
export function ProTableSearchBar<TData>({
  table,
  size,
  disabled = false,
}: {
  table: Table<TData>
  size?: ProButtonSize
  disabled?: boolean
}) {
  const buttonSize = size ?? 'sm'
  const searchColumns = getTableSearchColumns(table)
  const appliedFilters = table.getState().columnFilters
  const [draftFilters, setDraftFilters] = useState<ColumnFiltersState>(appliedFilters)
  const filterColumns = table
    .getAllColumns()
    .filter((column) => column.columnDef.meta?.filter !== undefined)

  useEffect(() => setDraftFilters(appliedFilters), [appliedFilters])

  if (searchColumns.length === 0 && filterColumns.length === 0) return null

  const setDraftFilterValue = (columnId: string, value: unknown) => {
    setDraftFilters((current) => {
      const next = current.filter((filter) => filter.id !== columnId)
      if (isEmptyFilterValue(value)) return next
      return [...next, { id: columnId, value }]
    })
  }
  const applyFilters = () => table.setColumnFilters(draftFilters)
  const hasConditions = draftFilters.length > 0 || appliedFilters.length > 0

  return (
    <search
      className="flex w-full flex-col gap-2 md:flex-row md:items-center md:justify-between"
      onKeyDown={(event) => {
        if (
          event.key !== 'Enter' ||
          !(event.target instanceof HTMLInputElement) ||
          !event.target.hasAttribute('data-pro-table-search-input')
        ) {
          return
        }
        event.preventDefault()
        applyFilters()
      }}
    >
      <div className="flex min-w-0 flex-1 flex-wrap items-start gap-2 md:items-center">
        {searchColumns.map((column) => {
          const rawValue = draftFilters.find((filter) => filter.id === column.id)?.value
          const value = typeof rawValue === 'string' ? rawValue : ''
          const configuredSearch = column.columnDef.meta?.search
          const placeholder = getSearchPlaceholder(
            column,
            typeof configuredSearch === 'object' ? configuredSearch.placeholder : undefined,
          )

          return (
            <Input
              key={`search-${column.id}`}
              data-pro-table-search-input=""
              aria-label={placeholder}
              placeholder={placeholder}
              value={value}
              onChange={(event) => setDraftFilterValue(column.id, event.target.value)}
              disabled={disabled}
              allowClear={false}
              inputClassName="h-8"
              className="w-full md:w-[200px]"
            />
          )
        })}
        {filterColumns.map((column) => {
          const filter = column.columnDef.meta?.filter
          if (!filter) return null
          const rawValue = draftFilters.find((item) => item.id === column.id)?.value
          const values = Array.isArray(rawValue)
            ? rawValue.filter((item): item is string => typeof item === 'string')
            : []

          return (
            <Select
              key={`filter-${column.id}`}
              options={filter.options.map((option) => {
                const count = column.getFacetedUniqueValues().get(option.value)
                return {
                  ...option,
                  label:
                    count === undefined ? (
                      option.label
                    ) : (
                      <span className="flex min-w-0 flex-1 items-center justify-between gap-3">
                        <span className="truncate">{option.label}</span>
                        <span className="shrink-0 font-mono text-xs text-muted-foreground">
                          {count}
                        </span>
                      </span>
                    ),
                }
              })}
              placeholder={filter.placeholder ?? column.id}
              multiple={filter.multiple}
              searchable
              allowClear
              disabled={disabled}
              value={getFilterValue(rawValue, values)}
              onChange={(value) => setDraftFilterValue(column.id, value)}
              className="h-8 w-full md:w-[180px]"
            />
          )
        })}
      </div>
      <div className="flex shrink-0 items-center justify-end gap-2">
        {hasConditions && (
          <ProButton
            type="button"
            variant="ghost"
            size={buttonSize}
            disabled={disabled}
            onClick={() => {
              setDraftFilters([])
              table.resetColumnFilters()
            }}
          >
            <X />
            Reset
          </ProButton>
        )}
        <ProButton type="button" size={buttonSize} disabled={disabled} onClick={applyFilters}>
          <Search />
          Search
        </ProButton>
      </div>
    </search>
  )
}

function getTableSearchColumns<TData>(table: Table<TData>) {
  return table
    .getAllLeafColumns()
    .filter(
      (column) =>
        column.columnDef.meta?.search !== undefined && column.columnDef.meta.search !== false,
    )
}

function getSearchPlaceholder<TData>(
  column: Column<TData, unknown>,
  configuredPlaceholder: string | undefined,
) {
  return configuredPlaceholder ?? `Search ${column.id}...`
}

function getFilterValue(rawValue: unknown, values: string[]) {
  if (typeof rawValue === 'string') return rawValue
  if (Array.isArray(rawValue) && values.length === rawValue.length) return values
  return undefined
}

function isEmptyFilterValue(value: unknown) {
  return (
    value === undefined ||
    value === null ||
    value === '' ||
    (Array.isArray(value) && value.length === 0)
  )
}

'use client'

import { compareItems, rankItem } from '@tanstack/match-sorter-utils'
import type {
  ColumnDef,
  ColumnPinningState,
  FilterFn,
  OnChangeFn,
  Row,
  SortingFn,
  Table,
} from '@tanstack/react-table'
import {
  type RefObject,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { cn } from '@/lib/utils'
import type { ProTablePinnedColumnOffsets } from './body'
import { getSystemColumnPinning } from './columns'

const useIsomorphicLayoutEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect

export interface ProTableTableOptions {
  stickyHeader?: boolean
  pinning?:
    | false
    | {
        value?: ColumnPinningState
        onChange?: (value: ColumnPinningState) => void
      }
}

export interface ColumnFilterMeta<TData> {
  options: Array<{
    label: string
    value: string
  }>
  placeholder?: string
  multiple?: boolean
  onFilter?: (value: string, record: TData) => boolean
}

function getColumnDefId<TData, TValue>(column: ColumnDef<TData, TValue>, index: number) {
  if (column.id) return column.id
  if ('accessorKey' in column && typeof column.accessorKey === 'string') return column.accessorKey
  return String(index)
}

function getLeafColumnIds<TData, TValue>(columns: ColumnDef<TData, TValue>[]): string[] {
  return columns.flatMap((column, index) =>
    'columns' in column && Array.isArray(column.columns)
      ? getLeafColumnIds(column.columns)
      : getColumnDefId(column, index),
  )
}

function getPinnedColumnIds<TData, TValue>(
  columns: ColumnDef<TData, TValue>[],
  side: 'left' | 'right',
): string[] {
  return columns.flatMap((column, index) => {
    if ('columns' in column && Array.isArray(column.columns)) {
      return getPinnedColumnIds(column.columns, side)
    }
    const id = getColumnDefId(column, index)
    const pinned = column.meta?.pinned ?? getSystemColumnPinning(id)
    return pinned === side ? [id] : []
  })
}

export function useProTableColumnState<TData, TValue>(
  columns: ColumnDef<TData, TValue>[],
  tableOptions: ProTableTableOptions | undefined,
) {
  const pinningEnabled = tableOptions?.pinning !== false
  const defaultColumnOrder = useMemo(() => getLeafColumnIds(columns), [columns])
  const defaultColumnPinning = useMemo(
    () =>
      pinningEnabled
        ? {
            left: getPinnedColumnIds(columns, 'left'),
            right: getPinnedColumnIds(columns, 'right'),
          }
        : {},
    [columns, pinningEnabled],
  )
  const defaultColumnPinningKey = `${defaultColumnPinning.left?.join('\0') ?? ''}\x01${defaultColumnPinning.right?.join('\0') ?? ''}`
  const defaultColumnPinningRef = useRef(defaultColumnPinning)
  defaultColumnPinningRef.current = defaultColumnPinning
  const controlledColumnPinning =
    typeof tableOptions?.pinning === 'object' ? tableOptions.pinning.value : undefined
  const [columnOrder, setColumnOrder] = useState<string[]>(defaultColumnOrder)
  const [internalColumnPinning, setInternalColumnPinning] =
    useState<ColumnPinningState>(defaultColumnPinning)
  const columnPinning =
    typeof tableOptions?.pinning === 'object' && tableOptions.pinning.value
      ? tableOptions.pinning.value
      : internalColumnPinning

  useEffect(() => {
    setColumnOrder((current) => {
      const remainingIds = new Set(defaultColumnOrder)
      const next = [...current.filter((id) => remainingIds.delete(id)), ...remainingIds]
      return next.length === current.length && next.every((id, index) => id === current[index])
        ? current
        : next
    })
  }, [defaultColumnOrder])
  useEffect(() => {
    if (!pinningEnabled || controlledColumnPinning) return
    setInternalColumnPinning(defaultColumnPinningRef.current)
  }, [controlledColumnPinning, defaultColumnPinningKey, pinningEnabled])

  const handleColumnPinningChange = useCallback<OnChangeFn<ColumnPinningState>>(
    (updater) => {
      const next = typeof updater === 'function' ? updater(columnPinning) : updater
      if (typeof tableOptions?.pinning === 'object') tableOptions.pinning.onChange?.(next)
      if (!(typeof tableOptions?.pinning === 'object' && tableOptions.pinning.value)) {
        setInternalColumnPinning(next)
      }
    },
    [columnPinning, tableOptions?.pinning],
  )

  return {
    columnOrder,
    setColumnOrder,
    columnPinning,
    handleColumnPinningChange,
    defaultColumnOrder,
    defaultColumnPinning,
    pinningEnabled,
  }
}

export function withProTableColumnDefaults<TData, TValue>(
  columns: ColumnDef<TData, TValue>[],
): ColumnDef<TData, TValue>[] {
  return columns.map((column, index) => {
    const children =
      'columns' in column && Array.isArray(column.columns)
        ? withProTableColumnDefaults(column.columns)
        : undefined
    const filter = column.meta?.filter
    const columnId = getColumnDefId(column, index)
    const search = column.meta?.search
    const shouldApplyFilter = filter && column.filterFn === undefined
    const shouldApplySearchFilter = search && !filter && column.filterFn === undefined
    const shouldApplyFuzzySort = search && column.sortingFn === undefined
    const systemPinned = getSystemColumnPinning(columnId)
    const fixedSize = column.size ?? (systemPinned ? 32 : undefined)

    if (
      !children &&
      !shouldApplyFilter &&
      !shouldApplySearchFilter &&
      !shouldApplyFuzzySort &&
      !systemPinned &&
      fixedSize === undefined
    ) {
      return column
    }

    return {
      ...column,
      ...(children ? { columns: children } : {}),
      ...(systemPinned
        ? {
            enableHiding: column.enableHiding ?? false,
            meta: {
              pinned: systemPinned,
              ...column.meta,
              ...(fixedSize === undefined ? {} : { __proTableFixedSize: fixedSize }),
              className: cn('w-8', column.meta?.className),
            },
          }
        : fixedSize === undefined
          ? {}
          : { meta: { ...column.meta, __proTableFixedSize: fixedSize } }),
      ...(shouldApplyFilter
        ? {
            filterFn: getColumnFilterFn(filter),
          }
        : {}),
      ...(shouldApplySearchFilter
        ? {
            filterFn: ((row, columnId, filterValue, addMeta) => {
              const value = String(filterValue ?? '')
              if (!value) return true

              const itemRank = rankItem(row.getValue(columnId), value)
              addMeta({ itemRank })
              return itemRank.passed
            }) satisfies FilterFn<TData>,
          }
        : {}),
      ...(shouldApplyFuzzySort
        ? {
            sortingFn: ((rowA, rowB, columnId) => {
              const rankA = rowA.columnFiltersMeta[columnId]?.itemRank
              const rankB = rowB.columnFiltersMeta[columnId]?.itemRank

              if (rankA && rankB) {
                const rankSort = compareItems(rankA, rankB)
                if (rankSort !== 0) return rankSort
              }

              return collator.compare(
                String(rowA.getValue(columnId) ?? ''),
                String(rowB.getValue(columnId) ?? ''),
              )
            }) satisfies SortingFn<TData>,
          }
        : {}),
    }
  })
}

function getColumnFilterFn<TData>(filter: ColumnFilterMeta<TData>) {
  if (filter.onFilter) {
    return ((row, _columnId, filterValue) => {
      if (filterValue === undefined || filterValue === null || filterValue === '') return true
      if (Array.isArray(filterValue)) {
        if (filterValue.length === 0) return true
        return filterValue.some((value) => filter.onFilter?.(String(value), row.original))
      }
      return !!filter.onFilter?.(String(filterValue), row.original)
    }) satisfies FilterFn<TData>
  }

  if (filter.multiple) {
    return ((row, columnId, filterValue) => {
      if (filterValue === undefined || filterValue === null || filterValue === '') return true
      const rowValue = row.getValue(columnId)
      if (Array.isArray(filterValue)) {
        if (filterValue.length === 0) return true
        return filterValue.includes(rowValue)
      }
      return filterValue === rowValue
    }) satisfies FilterFn<TData>
  }

  return 'equals'
}

const collator = new Intl.Collator(undefined, {
  numeric: true,
  sensitivity: 'base',
})

export function sortRowsByRank<TData>(rows: Row<TData>[], columnId: string) {
  return [...rows].sort((rowA, rowB) => {
    const rankA = rowA.columnFiltersMeta[columnId]?.itemRank
    const rankB = rowB.columnFiltersMeta[columnId]?.itemRank

    if (rankA && rankB) {
      const rankSort = compareItems(rankA, rankB)
      if (rankSort !== 0) return rankSort
    }

    if (rankA) return -1
    if (rankB) return 1
    return rowA.index - rowB.index
  })
}

export function useProTablePinnedColumnOffsets<TData>(
  table: Table<TData>,
  tableRef: RefObject<HTMLTableElement | null>,
  dragSort: boolean,
): ProTablePinnedColumnOffsets {
  const [offsets, setOffsets] = useState<ProTablePinnedColumnOffsets>(() =>
    getInitialPinnedColumnOffsets(table, dragSort),
  )
  const visibleColumnKey = table
    .getVisibleLeafColumns()
    .map((column) => column.id)
    .join('\0')
  const leftPinnedKey = (table.getState().columnPinning.left ?? []).join('\0')
  const rightPinnedKey = (table.getState().columnPinning.right ?? []).join('\0')
  const pinnedSizeKey = [
    ...table.getLeftVisibleLeafColumns(),
    ...table.getRightVisibleLeafColumns(),
  ]
    .map((column) => `${column.id}:${column.columnDef.meta?.__proTableFixedSize ?? 'auto'}`)
    .join('\0')

  useIsomorphicLayoutEffect(() => {
    const tableElement = tableRef.current
    if (!tableElement) return
    const measuredColumnIds = new Set(
      [...table.getLeftVisibleLeafColumns(), ...table.getRightVisibleLeafColumns()]
        .filter((column) => column.columnDef.meta?.__proTableFixedSize === undefined)
        .map((column) => column.id),
    )

    const updateOffsets = () => {
      const widths = new Map<string, number>()

      for (const element of tableElement.querySelectorAll<HTMLElement>(
        'thead tr:last-child [data-pro-table-column-id]',
      )) {
        const columnId = element.dataset.proTableColumnId
        if (!columnId || !measuredColumnIds.has(columnId) || widths.has(columnId)) continue
        widths.set(columnId, element.getBoundingClientRect().width)
      }

      const dragWidth = dragSort ? 32 : 0
      const next: ProTablePinnedColumnOffsets = { left: {}, right: {}, dragWidth }
      let left = dragWidth

      for (const column of table.getLeftVisibleLeafColumns()) {
        next.left[column.id] = left
        left +=
          column.columnDef.meta?.__proTableFixedSize ?? widths.get(column.id) ?? column.getSize()
      }

      let right = 0
      const rightColumns = table.getRightVisibleLeafColumns()
      for (let index = rightColumns.length - 1; index >= 0; index -= 1) {
        const column = rightColumns[index]
        next.right[column.id] = right
        right +=
          column.columnDef.meta?.__proTableFixedSize ?? widths.get(column.id) ?? column.getSize()
      }

      setOffsets((current) => (arePinnedColumnOffsetsEqual(current, next) ? current : next))
    }

    updateOffsets()
    if (typeof ResizeObserver === 'undefined' || measuredColumnIds.size === 0) return undefined

    let frame = 0
    const observer = new ResizeObserver(() => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(updateOffsets)
    })
    for (const element of tableElement.querySelectorAll<HTMLElement>(
      'thead tr:last-child [data-pro-table-column-id]',
    )) {
      const columnId = element.dataset.proTableColumnId
      if (columnId && measuredColumnIds.has(columnId)) observer.observe(element)
    }

    return () => {
      cancelAnimationFrame(frame)
      observer.disconnect()
    }
  }, [dragSort, leftPinnedKey, pinnedSizeKey, rightPinnedKey, table, tableRef, visibleColumnKey])

  return offsets
}

function getInitialPinnedColumnOffsets<TData>(table: Table<TData>, dragSort: boolean) {
  const offsets: ProTablePinnedColumnOffsets = {
    left: {},
    right: {},
    dragWidth: dragSort ? 32 : 0,
  }
  let left = offsets.dragWidth
  for (const column of table.getLeftVisibleLeafColumns()) {
    offsets.left[column.id] = left
    left += column.columnDef.meta?.__proTableFixedSize ?? column.getSize()
  }

  let right = 0
  const rightColumns = table.getRightVisibleLeafColumns()
  for (let index = rightColumns.length - 1; index >= 0; index -= 1) {
    const column = rightColumns[index]
    offsets.right[column.id] = right
    right += column.columnDef.meta?.__proTableFixedSize ?? column.getSize()
  }
  return offsets
}

function arePinnedColumnOffsetsEqual(
  current: ProTablePinnedColumnOffsets,
  next: ProTablePinnedColumnOffsets,
) {
  for (const side of ['left', 'right'] as const) {
    let currentCount = 0
    let nextCount = 0

    for (const [columnId, offset] of Object.entries(current[side])) {
      currentCount += 1
      if (next[side][columnId] !== offset) return false
    }

    for (const [columnId, offset] of Object.entries(next[side])) {
      nextCount += 1
      if (current[side][columnId] !== offset) return false
    }

    if (currentCount !== nextCount) return false
  }

  return current.dragWidth === next.dragWidth
}

