function ProTableColumnSettings<TData>({
  table,
  defaultColumnOrder,
  defaultColumnPinning,
}: {
  table: Table<TData>
  defaultColumnOrder: string[]
  defaultColumnPinning: ColumnPinningState
}) {
  const dragContextId = useId()
  const columns = table.getAllLeafColumns()
  const tableState = table.getState()
  const columnOrder = tableState.columnOrder.length ? tableState.columnOrder : defaultColumnOrder
  const columnLookup = new Map(columns.map((column) => [column.id, column] as const))
  const leftPinnedIds = new Set(tableState.columnPinning.left ?? [])
  const rightPinnedIds = new Set(tableState.columnPinning.right ?? [])
  const visualColumnOrder = [
    ...(tableState.columnPinning.left ?? []),
    ...columnOrder.filter(
      (columnId) => !leftPinnedIds.has(columnId) && !rightPinnedIds.has(columnId),
    ),
    ...(tableState.columnPinning.right ?? []),
  ]
  const orderedIds = new Set<string>()
  const orderedColumns = [
    ...visualColumnOrder.flatMap((columnId) => {
      const column = columnLookup.get(columnId)
      if (!column || orderedIds.has(column.id)) return []
      orderedIds.add(column.id)
      return [column]
    }),
    ...columns.filter((column) => {
      if (orderedIds.has(column.id)) return false
      orderedIds.add(column.id)
      return true
    }),
  ]
  const hideableColumns = orderedColumns.filter(
    (column) => column.getCanHide() && getSystemColumnPinning(column.id) === undefined,
  )
  const canPinColumns = table.options.enableColumnPinning !== false
  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  )

  return (
    <>
      <div className="flex items-center justify-between px-2 py-1.5">
        <span className="text-xs font-medium text-muted-foreground">Columns</span>
        <ProButton
          variant="ghost"
          size="xs"
          onClick={() => {
            table.resetColumnVisibility()
            table.setColumnOrder(defaultColumnOrder)
            if (canPinColumns) table.setColumnPinning(defaultColumnPinning)
          }}
        >
          <RotateCcw className="mr-1" />
          Reset
        </ProButton>
      </div>
      <div aria-hidden="true" className="h-px w-full shrink-0 bg-border" />
      <DndContext
        id={dragContextId}
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={({ active, over }) => {
          if (!over || active.id === over.id) return

          const activeId = String(active.id)
          const overId = String(over.id)
          const sortableOrder = hideableColumns.map((column) => column.id)
          const targetSide = columnLookup.get(overId)?.getIsPinned()
          const next = getColumnDropState({
            columnOrder,
            sortableOrder,
            columnPinning: tableState.columnPinning,
            activeId,
            overId,
            targetSide,
            pinningEnabled: canPinColumns,
          })
          if (!next) return

          table.setColumnOrder(next.order)
          if (canPinColumns) table.setColumnPinning(next.pinning)
        }}
      >
        <SortableContext
          items={hideableColumns.map((column) => column.id)}
          strategy={verticalListSortingStrategy}
        >
          <div className="py-1">
            {hideableColumns.map((column) => (
              <SortableColumnItem key={column.id} column={column} canPin={canPinColumns} />
            ))}
          </div>
        </SortableContext>
      </DndContext>
    </>
  )
}

function SortableColumnItem<TData>({
  column,
  canPin,
}: {
  column: Column<TData, unknown>
  canPin: boolean
}) {
  const checkboxId = useId()
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: column.id,
  })
  const pinned = column.getIsPinned()
  const canPinColumn = canPin && column.getCanPin()
  const leftPinned = pinned === 'left'
  const rightPinned = pinned === 'right'

  return (
    <div
      ref={setNodeRef}
      style={{
        transform: CSS.Transform.toString(transform),
        transition,
        opacity: isDragging ? 0.5 : 1,
      }}
      className="flex items-center gap-1 px-2 py-1.5 text-sm"
    >
      <ProButton
        variant="link"
        size="icon-xs"
        {...attributes}
        {...listeners}
        className="cursor-grab text-muted-foreground no-underline hover:text-foreground hover:no-underline active:cursor-grabbing"
        aria-label="Drag to reorder"
      >
        <GripVertical />
      </ProButton>
      {canPinColumn && (
        <ProButton
          variant={leftPinned ? 'secondary' : 'ghost'}
          size="icon-xs"
          className="shrink-0"
          aria-pressed={leftPinned}
          aria-label={leftPinned ? 'Unpin left' : 'Pin left'}
          title={leftPinned ? 'Unpin left' : 'Pin left'}
          onPointerDown={(event) => event.stopPropagation()}
          onClick={(event) => {
            event.stopPropagation()
            column.pin(leftPinned ? false : 'left')
          }}
        >
          {leftPinned ? <PinOff /> : <Pin />}
        </ProButton>
      )}
      <label
        htmlFor={checkboxId}
        className="flex min-w-0 flex-1 cursor-pointer items-center gap-2 select-none"
      >
        <CheckboxControl
          id={checkboxId}
          checked={column.getIsVisible()}
          disabled={!column.getCanHide()}
          onCheckedChange={(checked) => column.toggleVisibility(checked === true)}
          onClick={(event) => event.stopPropagation()}
        />
        <span className="truncate">
          {typeof column.columnDef.header === 'string' ? column.columnDef.header : column.id}
        </span>
      </label>
      {canPinColumn && (
        <ProButton
          variant={rightPinned ? 'secondary' : 'ghost'}
          size="icon-xs"
          className="shrink-0"
          aria-pressed={rightPinned}
          aria-label={rightPinned ? 'Unpin right' : 'Pin right'}
          title={rightPinned ? 'Unpin right' : 'Pin right'}
          onPointerDown={(event) => event.stopPropagation()}
          onClick={(event) => {
            event.stopPropagation()
            column.pin(rightPinned ? false : 'right')
          }}
        >
          {rightPinned ? <PinOff /> : <Pin />}
        </ProButton>
      )}
    </div>
  )
}

'use client'

import type { ColumnFiltersState, PaginationState, SortingState } from '@tanstack/react-table'
import { useCallback, useMemo } from 'react'

/** Internal table state shape shared with the public entry point. */
export interface ProTableStateValue {
  pagination: PaginationState
  sorting: SortingState
  columnFilters: ColumnFiltersState
}

/** Internal URL mapping for a table filter. */
export type UrlColumnFilterConfig =
  | {
      columnId: string
      searchKey: string
      type?: 'string'
      serialize?: (value: unknown) => unknown
      deserialize?: (value: unknown) => unknown
    }
  | {
      columnId: string
      searchKey: string
      type: 'array'
      serialize?: (value: unknown) => unknown
      deserialize?: (value: unknown) => unknown
    }

/** Internal implementation of the public URL state hook. */
export function useProTableUrlStateValue(params: {
  search: Record<string, unknown>
  navigate: (opts: {
    search:
      | true
      | Record<string, unknown>
      | ((
          prev: Record<string, unknown>,
        ) => Partial<Record<string, unknown>> | Record<string, unknown>)
    replace?: boolean
  }) => void
  pagination?: {
    pageKey?: string
    pageSizeKey?: string
    defaultPage?: number
    defaultPageSize?: number
  }
  sorting?: {
    sortKey?: string
    orderKey?: string
  }
  columnFilters?: UrlColumnFilterConfig[]
}): {
  initialState: Partial<ProTableStateValue>
  onChange: (state: ProTableStateValue) => void
} {
  const {
    search,
    navigate,
    pagination: paginationCfg,
    sorting: sortingCfg,
    columnFilters: columnFiltersCfg,
  } = params
  const pageKey = paginationCfg?.pageKey ?? 'page'
  const pageSizeKey = paginationCfg?.pageSizeKey ?? 'pageSize'
  const defaultPage = Math.max(1, paginationCfg?.defaultPage ?? 1)
  const defaultPageSize = Math.max(1, paginationCfg?.defaultPageSize ?? 10)
  const sortKey = sortingCfg?.sortKey ?? 'sort'
  const orderKey = sortingCfg?.orderKey ?? 'order'

  const initialState = useMemo<Partial<ProTableStateValue>>(() => {
    const page = typeof search[pageKey] === 'number' ? search[pageKey] : Number(search[pageKey])
    const pageSize =
      typeof search[pageSizeKey] === 'number' ? search[pageSizeKey] : Number(search[pageSizeKey])
    const normalizedPage = Number.isFinite(page) && page > 0 ? Math.floor(page) : defaultPage
    const normalizedPageSize =
      Number.isFinite(pageSize) && pageSize > 0 ? Math.floor(pageSize) : defaultPageSize
    const sortId = search[sortKey]
    const columnFilters: ColumnFiltersState = []

    for (const cfg of columnFiltersCfg ?? []) {
      const value = cfg.deserialize ? cfg.deserialize(search[cfg.searchKey]) : search[cfg.searchKey]
      if (cfg.type === 'array') {
        if (Array.isArray(value) && value.length > 0) {
          columnFilters.push({ id: cfg.columnId, value })
        }
        continue
      }
      if (typeof value === 'string' && value.trim() !== '') {
        columnFilters.push({ id: cfg.columnId, value })
      }
    }

    const sorting: SortingState =
      typeof sortId === 'string' && sortId.trim() !== ''
        ? [{ id: sortId, desc: search[orderKey] === 'desc' }]
        : []

    return {
      pagination: {
        pageIndex: normalizedPage - 1,
        pageSize: normalizedPageSize,
      },
      sorting,
      columnFilters,
    }
  }, [
    columnFiltersCfg,
    defaultPage,
    defaultPageSize,
    orderKey,
    pageKey,
    pageSizeKey,
    search,
    sortKey,
  ])

  const onChange = useCallback(
    (state: ProTableStateValue) => {
      const sorting = state.sorting[0]
      const patch: Record<string, unknown> = {
        [pageKey]: undefined,
        [pageSizeKey]: undefined,
        [sortKey]: undefined,
        [orderKey]: undefined,
      }

      const nextPage = state.pagination.pageIndex + 1
      if (nextPage !== defaultPage) patch[pageKey] = nextPage
      if (state.pagination.pageSize !== defaultPageSize) {
        patch[pageSizeKey] = state.pagination.pageSize
      }
      if (sorting) {
        patch[sortKey] = sorting.id
        patch[orderKey] = sorting.desc ? 'desc' : 'asc'
      }

      const filterValues = new Map(
        state.columnFilters.map((filter) => [filter.id, filter.value] as const),
      )
      for (const cfg of columnFiltersCfg ?? []) {
        const filterValue = filterValues.get(cfg.columnId)
        patch[cfg.searchKey] = undefined

        if (cfg.type === 'array') {
          const value = Array.isArray(filterValue) ? filterValue : []
          if (value.length > 0) patch[cfg.searchKey] = cfg.serialize?.(value) ?? value
          continue
        }

        const value = typeof filterValue === 'string' ? filterValue : ''
        if (value.trim() !== '') patch[cfg.searchKey] = cfg.serialize?.(value) ?? value
      }

      navigate({ search: (previous) => ({ ...previous, ...patch }) })
    },
    [
      columnFiltersCfg,
      defaultPage,
      defaultPageSize,
      navigate,
      orderKey,
      pageKey,
      pageSizeKey,
      sortKey,
    ],
  )

  return { initialState, onChange }
}
